/**
 * L1 Automated Triage — Cart (user-behavior) Canary.
 *
 * A CloudWatch Synthetics Puppeteer canary that exercises the actual
 * "Add to cart" write path on the Buy Food page, rather than only
 * checking that the catalog page loads. This closes a coverage gap left
 * by the read-only page-load checks in the health/UX canaries: those
 * canaries confirm the catalog renders (GET /api/foods) but never click
 * "Add to cart" (POST /api/cart/{userId}/items), so a bug in the
 * downstream cart service could silently break checkout for real users
 * while both of those canaries continue to report healthy.
 *
 * The check:
 *   1. Loads the Buy Food page.
 *   2. Waits for the catalog to render (a food card with an
 *      "Add to cart" button) — a precondition, not the assertion itself.
 *   3. Records the cart count badge's value before clicking (it may be
 *      hidden/empty if the cart starts empty).
 *   4. Clicks the "Add to cart" button on the first available food item.
 *   5. Waits for the cart count badge to become visible and show a
 *      value greater than the pre-click value.
 *
 * This is a positive, end-to-end functional assertion: the AJAX call
 * completing without an HTTP error is not sufficient on its own, because
 * the PetSite backend (FoodServiceController.AddToCart) swallows
 * downstream cart-API failures into a 200 response with totalItems: 0
 * rather than surfacing them as a failed request. Asserting on the
 * actual displayed cart count is what catches that failure mode.
 *
 * A failure drives an `l1t-health-` prefixed availability alarm, so a
 * broken "Add to cart" flow enters the same routing -> DevOps Agent
 * triage flow as the other L1 canaries.
 *
 * Configuration (environment variables set by the construct):
 *   L1T_CART_URL_PARAMETER_NAME   SSM parameter holding the base site URL
 *   L1T_CART_URL                  inline base site URL (takes precedence)
 *   L1T_CART_ADD_SELECTOR         CSS selector of the "Add to cart" button (default: .add-to-cart)
 *   L1T_CART_COUNT_SELECTOR       CSS selector of the cart count badge (default: #cart-count)
 *   L1T_CART_USER_ID              query param appended to the page URL (default: user63606)
 *   L1T_CART_UPDATE_TIMEOUT_MS    max time to wait for the cart count to update, in ms (default: 5000)
 */

'use strict';

// The Synthetics runtime provides these modules only inside a canary. Load
// them lazily/tolerantly so the pure decision logic can be unit-tested
// outside the runtime.
let synthetics;
let log;
try {
    // eslint-disable-next-line global-require
    synthetics = require('Synthetics');
    // eslint-disable-next-line global-require
    log = require('SyntheticsLogger');
} catch (e) {
    synthetics = {
        executeStep: async (_name, fn) => fn(),
        getPage: async () => {
            throw new Error('Synthetics runtime not available (getPage requires the canary runtime)');
        },
        takeScreenshot: async () => {},
    };
    log = { info: () => {}, error: () => {} };
}

async function resolveUrl() {
    const inline = process.env.L1T_CART_URL;
    if (inline && inline.trim().length > 0) {
        return inline.trim();
    }
    const paramName = process.env.L1T_CART_URL_PARAMETER_NAME;
    if (!paramName) {
        throw new Error('No cart target URL configured (set L1T_CART_URL or L1T_CART_URL_PARAMETER_NAME)');
    }
    const { SSMClient, GetParameterCommand } = require('@aws-sdk/client-ssm');
    const ssm = new SSMClient({});
    const res = await ssm.send(new GetParameterCommand({ Name: paramName, WithDecryption: false }));
    if (!res.Parameter || !res.Parameter.Value) {
        throw new Error(`SSM parameter ${paramName} has no value`);
    }
    return res.Parameter.Value;
}

/**
 * Read the cart count badge's current numeric value. Returns 0 if the
 * badge is absent, hidden, or has no parseable numeric text (an empty or
 * hidden badge means "0 items", which is the correct starting state for
 * an empty cart — this mirrors the visibility-aware selector checks used
 * by the L1 UX canary, since a hidden, empty badge is not itself a
 * failure signal, only a starting value).
 *
 * @param {import('puppeteer').Page} page
 * @param {string} selector
 * @returns {Promise<number>}
 */
async function readCartCount(page, selector) {
    try {
        return await page.evaluate((sel) => {
            const el = document.querySelector(sel);
            if (!el) {
                return 0;
            }
            const style = window.getComputedStyle(el);
            if (style.display === 'none' || style.visibility === 'hidden') {
                return 0;
            }
            const text = (el.textContent || '').trim();
            const value = Number.parseInt(text, 10);
            return Number.isNaN(value) ? 0 : value;
        }, selector);
    } catch (e) {
        return 0;
    }
}

/**
 * Poll the cart count badge until it is greater than `beforeCount`, or
 * until `timeoutMs` elapses. Polling (rather than a single check) is
 * necessary because the badge is updated asynchronously by the AJAX
 * success handler after the click, not synchronously with it.
 *
 * @param {import('puppeteer').Page} page
 * @param {string} selector
 * @param {number} beforeCount
 * @param {number} timeoutMs
 * @returns {Promise<number>} the observed count when it increased, or the last observed count on timeout
 */
async function waitForCartCountIncrease(page, selector, beforeCount, timeoutMs) {
    const pollIntervalMs = 250;
    const deadline = Date.now() + timeoutMs;
    let lastObserved = beforeCount;
    while (Date.now() < deadline) {
        lastObserved = await readCartCount(page, selector);
        if (lastObserved > beforeCount) {
            return lastObserved;
        }
        await new Promise((r) => setTimeout(r, pollIntervalMs));
    }
    return lastObserved;
}

/**
 * Pure decision logic: given the observed before/after cart counts, decide
 * whether the "Add to cart" action succeeded. Kept separate from the
 * Puppeteer I/O above so it is directly unit-testable.
 *
 * @param {{beforeCount:number, afterCount:number, buttonFound:boolean}} signals
 * @returns {{ok:boolean, reason:(string|null)}}
 */
function evaluateCartResult(signals) {
    if (!signals.buttonFound) {
        return { ok: false, reason: 'Add to cart button was not found on the page' };
    }
    if (signals.afterCount <= signals.beforeCount) {
        return {
            ok: false,
            reason: `Cart count did not increase after clicking Add to cart (before=${signals.beforeCount}, after=${signals.afterCount})`,
        };
    }
    return { ok: true, reason: null };
}

const cartCheckBlueprint = async function () {
    const baseUrl = (await resolveUrl()).replace(/\/$/, '');
    const addToCartSelector = process.env.L1T_CART_ADD_SELECTOR || '.add-to-cart';
    const cartCountSelector = process.env.L1T_CART_COUNT_SELECTOR || '#cart-count';
    const userId = process.env.L1T_CART_USER_ID || 'user63606';
    const updateTimeoutMs = Number(process.env.L1T_CART_UPDATE_TIMEOUT_MS) || 5000;

    const url = `${baseUrl}/FoodService?userId=${userId}`;
    const page = await synthetics.getPage();

    await synthetics.executeStep('add-to-cart', async function () {
        await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 30000 });

        // Precondition: the catalog must render before we can click
        // anything on it. This is not the assertion itself — a missing
        // catalog is reported distinctly from a broken add-to-cart click.
        await page.waitForSelector(addToCartSelector, { timeout: 10000 }).catch(() => {});

        const buttonFound = (await page.$(addToCartSelector)) !== null;
        const beforeCount = await readCartCount(page, cartCountSelector);

        let afterCount = beforeCount;
        if (buttonFound) {
            await page.click(addToCartSelector);
            afterCount = await waitForCartCountIncrease(page, cartCountSelector, beforeCount, updateTimeoutMs);
        }

        const result = evaluateCartResult({ beforeCount, afterCount, buttonFound });

        log.info(
            JSON.stringify({
                l1tCartCheck: true,
                url,
                buttonFound,
                beforeCount,
                afterCount,
                ok: result.ok,
                timestamp: new Date().toISOString(),
            }),
        );

        if (!result.ok) {
            throw new Error(result.reason);
        }
    });
    await synthetics.takeScreenshot('add-to-cart', 'result');
};

exports.handler = async () => {
    return await cartCheckBlueprint();
};

// Exported for unit testing (ignored by the Synthetics runtime).
exports.__test__ = {
    evaluateCartResult,
    readCartCount,
    waitForCartCountIncrease,
};
